metrics.workdir_dsl:
workspace "Home Energy Management Platform" "C4 model of the Energy Manager platform" {

    !identifiers hierarchical

    model {

        homeowner = person "Homeowner" "Manages their household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "Platform for managing household energy use and costs" {

            dashboard = container "Dashboard" "Web app where homeowners see consumption and costs" "Web app" "Web" {
                rates = component "Rates Library" "Computes energy prices from tariff and time of day" "Shared library"
            }

            scheduler = container "Scheduling Service" "Plans charging and heating" "Service" {
                rates = component "Rates Library" "Computes energy prices from tariff and time of day" "Shared library"
            }

            database = container "Database" "Stores meter readings and schedules" "Database" "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Operated by a different organization; provides live meter readings" "External"

        homeowner -> energyManager.dashboard "views consumption and costs" "HTTPS"
        energyManager.dashboard -> energyManager.database "reads meter readings from" "SQL"
        energyManager.scheduler -> smartMeterProvider "fetches live meter readings from" "HTTP/JSON"
        energyManager.scheduler -> energyManager.database "stores meter readings and schedules in" "SQL"
    }

    views {

        systemContext energyManager "SystemContext" {
            include *
            autoLayout
            title "System Context for Energy Manager"
        }

        container energyManager "Containers" {
            include *
            autoLayout
            title "Containers for Energy Manager"
        }

        component energyManager.dashboard "DashboardComponents" {
            include *
            autoLayout
            title "Components of Dashboard"
        }

        component energyManager.scheduler "SchedulerComponents" {
            include *
            autoLayout
            title "Components of Scheduling Service"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
        }
    }
}
